B.bl_=s(["Pap\xe1 tiene un reloj de pulsera.","B\u1ed1 c\xf3 \u0111\u1ed3ng h\u1ed3 \u0111eo tay."],t.s)
B.bqp=s(["La sand\xeda es dulce.","D\u01b0a h\u1ea5u ng\u1ecdt."],t.s)
B.bQe=s(["Bebo leche.","T\xf4i u\u1ed1ng s\u1eefa."],t.s)
B.bbU=s(["El pan huele rico.","B\xe1nh m\xec th\u01a1m qu\xe1."],t.s)
B.b_Q=s(["Como un huevo.","T\xf4i \u0103n tr\u1ee9ng."],t.s)
B.bUk=s(["El arroz es rico.","C\u01a1m ngon."],t.s)
B.aTk=s(["Las fresas son rojas y dulces.","D\xe2u t\xe2y \u0111\u1ecf v\xe0 ng\u1ecdt."],t.s)
B.bZx=s(["El pastel de cumplea\xf1os es grande.","B\xe1nh sinh nh\u1eadt to."],t.s)
B.atM=s(["Mam\xe1 hace empanadillas.","M\u1eb9 g\xf3i b\xe1nh bao."],t.s)
B.a73=s(["Los fideos son largos.","S\u1ee3i m\xec d\xe0i."],t.s)
B.bSd=s(["La luna es redonda.","M\u1eb7t tr\u0103ng tr\xf2n."],t.s)
B.NM=s(["Juego con mi amigo.","T\xf4i ch\u01a1i v\u1edbi b\u1ea1n."],t.s)
B.b07=s(["Hay muchas estrellas en el cielo.","Tr\xean tr\u1eddi c\xf3 nhi\u1ec1u sao."],t.s)
B.y1=s(["Las nubes blancas flotan en el cielo.","M\xe2y tr\u1eafng tr\xf4i tr\xean b\u1ea7u tr\u1eddi."],t.s)
B.aT7=s(["Quiero a mi mam\xe1.","T\xf4i y\xeau m\u1eb9."],t.s)
B.a3i=s(["\xa1Hola, maestra!","Em ch\xe0o c\xf4 \u1ea1!"],t.s)
B.aiP=s(["El mar es azul.","Bi\u1ec3n xanh."],t.s)
B.B0=s(["Hacemos un mu\xf1eco de nieve.","Ch\xfang t\xf4i l\xe0m ng\u01b0\u1eddi tuy\u1ebft."],t.s)
B.bAB=s(["Vamos a jugar al parque.","Ch\xfang t\xf4i \u0111i ch\u01a1i c\xf4ng vi\xean."],t.s)
B.brJ=s(["Hay m\xe9dicos en el hospital.","\u1ede b\u1ec7nh vi\u1ec7n c\xf3 b\xe1c s\u0129."],t.s)
B.b5E=s(["El sal\xf3n de clases est\xe1 limpio.","L\u1edbp h\u1ecdc s\u1ea1ch s\u1ebd."],t.s)
B.aWR=s(["El m\xe9dico me revisa.","B\xe1c s\u0129 kh\xe1m b\u1ec7nh cho t\xf4i."],t.s)
B.bXK=s(["El polic\xeda ayuda a todos.","Ch\xfa c\u1ea3nh s\xe1t gi\xfap \u0111\u1ee1 m\u1ecdi ng\u01b0\u1eddi."],t.s)
B.amS=s(["El cocinero prepara la comida.","\u0110\u1ea7u b\u1ebfp n\u1ea5u c\u01a1m."],t.s)
B.ahf=s(["Vamos de compras al supermercado.","Ch\xfang t\xf4i \u0111i si\xeau th\u1ecb mua \u0111\u1ed3."],t.s)
B.aee=s(["El estudiante escribe.","H\u1ecdc sinh vi\u1ebft ch\u1eef."],t.s)
B.aDK=s(["La maestra escribe en el pizarr\xf3n.","C\xf4 gi\xe1o vi\u1ebft ch\u1eef l\xean b\u1ea3ng."],t.s)
B.Wb=s(["Ten cuidado al cruzar la calle.","H\xe3y c\u1ea9n th\u1eadn khi qua \u0111\u01b0\u1eddng."],t.s)
B.Bl=s(["Las flores florecen en primavera.","M\xf9a xu\xe2n hoa n\u1edf."],t.s)
B.I9=s(["El verano es caluroso.","M\xf9a h\xe8 n\xf3ng."],t.s)
B.a9i=s(["En oto\xf1o las hojas se ponen amarillas.","M\xf9a thu l\xe1 c\xe2y chuy\u1ec3n v\xe0ng."],t.s)
B.b1o=s(["El invierno es fr\xedo.","M\xf9a \u0111\xf4ng l\u1ea1nh."],t.s)
B.Zl=s(["El rel\xe1mpago destella.","Tia ch\u1edbp l\xf3e s\xe1ng."],t.s)
B.baU=s(["Jugamos en la playa.","Ch\xfang t\xf4i ch\u01a1i tr\xean b\xe3i c\xe1t."],t.s)
B.bDG=s(["Me gusta escuchar m\xfasica.","T\xf4i th\xedch nghe nh\u1ea1c."],t.s)
B.atl=s(["Jugamos f\xfatbol.","Ch\xfang t\xf4i ch\u01a1i b\xf3ng \u0111\xe1."],t.s)
B.aI_=s(["Hoy es mi cumplea\xf1os.","H\xf4m nay l\xe0 sinh nh\u1eadt t\xf4i."],t.s)
B.ab8=s(["El panda gigante es lindo.","G\u1ea5u tr\xfac l\u1edbn d\u1ec5 th\u01b0\u01a1ng."],t.s)
B.a24=s(["El conejo blanco salta y salta.","Th\u1ecf tr\u1eafng nh\u1ea3y tung t\u0103ng."],t.s)
B.KW=s(["Al oso polar no le da fr\xedo.","G\u1ea5u B\u1eafc C\u1ef1c kh\xf4ng s\u1ee3 l\u1ea1nh."],t.s)
B.a5z=s(["El b\xfaho no duerme de noche.","C\xfa m\xe8o kh\xf4ng ng\u1ee7 v\xe0o ban \u0111\xeam."],t.s)
B.Dz=s(["La luci\xe9rnaga brilla.","\u0110om \u0111\xf3m ph\xe1t s\xe1ng."],t.s)
B.asF=s(["La oruga se convierte en mariposa.","S\xe2u b\u01b0\u1edbm h\xf3a th\xe0nh b\u01b0\u1edbm."],t.s)
B.a_7=s(["El p\xe1jaro carpintero picotea el \xe1rbol.","Chim g\xf5 ki\u1ebfn m\u1ed5 v\xe0o c\xe2y."],t.s)
B.aZL=s(["Las semillas del diente de le\xf3n vuelan.","H\u1ea1t b\u1ed3 c\xf4ng anh bay l\xean."],t.s)
B.a3H=s(["Voy a la estaci\xf3n de tren.","T\xf4i \u0111i ra ga t\xe0u."],t.s)
B.bcl=s(["S\xe9 andar en bicicleta.","T\xf4i bi\u1ebft \u0111i xe \u0111\u1ea1p."],t.s)
B.bGk=s(["Hay muchos libros en la biblioteca.","Th\u01b0 vi\u1ec7n c\xf3 nhi\u1ec1u s\xe1ch."],t.s)
B.azW=s(["Hay un elefante en el zool\xf3gico.","\u1ede s\u1edf th\xfa c\xf3 con voi."],t.s)
B.aA_=s(["El parque de diversiones es muy divertido.","C\xf4ng vi\xean gi\u1ea3i tr\xed th\u1eadt l\xe0 vui."],t.s)
B.bvC=s(["El helado es fr\xedo y dulce.","Kem m\xe1t l\u1ea1nh v\xe0 ng\u1ecdt."],t.s)
B.VG=s(["El chocolate es dulce.","S\xf4-c\xf4-la ng\u1ecdt ng\xe0o."],t.s)
B.as8=s(["El sem\xe1foro se puso en verde.","\u0110\xe8n giao th\xf4ng chuy\u1ec3n sang xanh."],t.s)
B.ak0=s(["El robot baila.","R\xf4-b\u1ed1t nh\u1ea3y m\xfaa."],t.s)
